#!/usr/bin/env python3
"""Focused converter invariants; real captures are regenerated by build_owner010.sh."""
import struct,unittest
from compile_owner import compact,context
class ConverterTests(unittest.TestCase):
 def data(self,pages):
  n=len(pages)*4096
  return bytes((i*13+7)&255 for i in range(n)),bytes(n),bytearray(n),bytearray(n)
 def test_contiguous_64_plan_preserves_input(self):
  pages=[0x40000000+4096*i for i in range(70)];b,a,m,w=self.data(pages)
  for i in range(70):m[i*4096+128]=1
  rs,bs,_,_=compact(pages,b,a,m,w,0x70001000)
  self.assertEqual(len(rs),64)
  for lo,n,off in rs:self.assertEqual(bs[off:off+n],b[lo-pages[0]:lo-pages[0]+n])
 def test_64_discontiguous_regions(self):
  pages=[0x40000000+8192*i for i in range(64)];b,a,m,w=self.data(pages)
  for i in range(64):m[i*4096+32]=1
  rs,bs,_,_=compact(pages,b,a,m,w,0x70001000)
  self.assertEqual(len(rs),64);self.assertEqual(len(bs),64*16)
  for i,(lo,n,off)in enumerate(rs):
   self.assertEqual((lo,n),(pages[i]+32,16));self.assertEqual(bs[off:off+n],b[i*4096+32:i*4096+48])
 def test_absent_gap_never_filled(self):
  pages=[0x40000000+8192*i for i in range(65)];b,a,m,w=self.data(pages)
  for i in range(65):m[i*4096]=1
  with self.assertRaisesRegex(ValueError,'discontiguous'):compact(pages,b,a,m,w,0x70001000)
 def test_page_geometry(self):
  for pages in ([],[4096,4096],[8192,4096],[4097],[-4096],[0x100000000]):
   with self.subTest(pages=pages):
    with self.assertRaises(ValueError):compact(pages,b'',b'',b'',b'',0x70001000)
 def test_source_length(self):
  b,a,m,w=self.data([4096])
  with self.assertRaises(ValueError):compact([4096],b[:-1],a,m,w,0x70001000)
 def test_access_mask_values(self):
  b,a,m,w=self.data([4096]);m[0]=2
  with self.assertRaises(ValueError):compact([4096],b,a,m,w,0x70001000)
 def test_write_mask_values(self):
  b,a,m,w=self.data([4096]);w[0]=2
  with self.assertRaises(ValueError):compact([4096],b,a,m,w,0x70001000)
 def test_compact_capacity(self):
  pages=[0x40000000+4096*i for i in range(65)];b,a,m,w=self.data(pages);m[:]=b'\1'*len(m)
  with self.assertRaisesRegex(ValueError,'capacity'):compact(pages,b,a,m,w,0x70001000)
 def test_context_exact_size(self):
  m=dict(gpr=list(range(32)),fpr=list(range(32)),lr=4,ctr=8,cr=[0]*8,xer=[0]*3,fpscr=0)
  c=context(m);self.assertEqual(len(c),544);self.assertEqual(struct.unpack_from('<Q',c,31*8)[0],31)
 def test_context_rejects_invalid_flags(self):
  m=dict(gpr=[0]*32,fpr=[0]*32,lr=0,ctr=0,cr=[0]*8,xer=[0]*3,fpscr=0)
  for key,val in [('cr',[16]*8),('xer',[2]*3),('gpr',[0]*31)]:
   with self.subTest(key=key):
    bad=dict(m);bad[key]=val
    with self.assertRaises(ValueError):context(bad)
if __name__=='__main__':unittest.main(verbosity=2)
